import "fmt"

type node struct {
	val         int
	left, right *node
}

func insert(n *node, v int) *node {
	if n == nil {
		return &node{val: v}
	}
	if v < n.val {
		n.left = insert(n.left, v)
	} else {
		n.right = insert(n.right, v)
	}
	return n
}

func walk(n *node, out *[]int) {
	if n == nil {
		return
	}
	walk(n.left, out)
	*out = append(*out, n.val)
	walk(n.right, out)
}

func main() {
	var root *node
	for _, v := range []int{5, 3, 8, 1} {
		root = insert(root, v)
	}
	var out []int
	walk(root, &out)
	fmt.Println(out)
}

